get_first_consult_dt = lambda e: min([j['journal_datetime'] for j in e['JOURNALS']]) if e['JOURNALS'] != [] else 999999999
get_first_date_ep_or_consult = lambda p: min([ min(e['episode_start_date'], get_first_consult_dt(e)) for e in p['Episodes']])

def set_cohort_flwp_start_end(pats_dict, cohort):
    first_dates = [get_first_date_ep_or_consult(p) for p in pats_dict.values()]
    cohort['t_flwp_start'] = first_dates
    # fix var_obs_end for HF+ cases (it was NaN..) VAR_FOLLOW_UP_DATE
    cohort.loc[pd.isnull(cohort[VAR_OBSERVATION_END]), [VAR_OBSERVATION_END]] = cohort[pd.isnull(cohort[VAR_OBSERVATION_END])][VAR_FOLLOW_UP_DATE]
    cohort['t_dur'] = cohort[VAR_OBSERVATION_END] - cohort.t_flwp_start
    return cohort
    # try_table(cohort['t_dur'])

