bin_coi = try_sd(coi, non_bin_coi)
cols = coi + ['gmm_cls'] 

def gen_groups(df, col='gmm_cls'):
    for col_v, ss_df in df.groupby([col]):
        yield col_v, ss_df
    yield "ALL", df


bin_coi_vcs = {k:nuniq(cohort[k]) for k in bin_coi}
needs_binerise = [k for k,v in bin_coi_vcs.items() if v > 2]
sex_map = { 'V' : 0, 'M' : 1, 'N': None, 'O': None}
cohort['is_male'] = [sex_map[v] for v in cohort['sex']]
bin_coi += ['is_male']
cols += ['is_male']
try_table(cohort['is_male'])
for c in needs_binerise:
    cohort[c] = ~pd.isnull(cohort[c])

res = []
bin_coi = sorted(bin_coi)
bin_coi_fancy = [x[2:-2] if x.endswith('_y') else x[2:] for x in bin_coi]
bin_coi_fancy = [x.replace('_', ' ').strip() for x in bin_coi_fancy]
# bin_coi_fancy = sorted(bin_coi_fancy)
res_colnames = ['Cluster ID', 'n'] 
for bc in bin_coi_fancy:
    res_colnames = res_colnames + [bc, f"{bc}%", f"{bc}(%)"]
for nbc in non_bin_coi:
    res_colnames = res_colnames + [nbc, f"{nbc}_IQR", f"{nbc}(IQR)" ]

res_colnames += ['CR per 1000 person-years']
precisions_non_bin_coi = { c:0 for c in non_bin_coi}
precisions_non_bin_coi['targetHF_score'] = 1
precisions_non_bin_coi['0_24_n_eps_'] = 1


cohort.t_birth = round((cohort['follow_up_LAST'] +  cohort['age_days'] ) / 365)  # convert to age years, todo: rename t_birth to age_days

for gmm_id, gmm_df in gen_groups(cohort[cols], 'gmm_cls'):
    c_res = [gmm_id, nrow(gmm_df)]
    # % stuff
    for bc, bcf in zip(bin_coi, bin_coi_fancy): # try_print_list([ f"bc={a} \#->{b}" for a,b in zip(bin_coi, bin_coi_fancy)], logger)
        c_df = gmm_df[~pd.isnull(gmm_df[bc])]
        n1s = try_table(c_df[bc]).to_dict()[1]
        c_res+=[n1s]
        percent_1s = 100*n1s / nrow(c_df)
        c_res+=[percent_1s]
        c_res+=[f"{n1s} ({percent_1s:.1f})" ]

    # IQR stuff
    for nbc in non_bin_coi:
        c_df = gmm_df[~pd.isnull(gmm_df[nbc])] # todo: missing count
        decimals = precisions_non_bin_coi[nbc]
        c_iqr = np.quantile(c_df[nbc], [0.25, 0.75])
        c_iqr = f"{c_iqr[0]:.{decimals}f}; {c_iqr[1]:.{decimals}f}"
        c_median = np.median(c_df[nbc])
        if nbc not in ['targetHF_score', 't_dur', 't_birth', '0_24_n_eps_']:
            c_median = f"'{conv_date_days_to_str(c_median)}'"
            c_iqr = [conv_date_days_to_str(v) for v in np.quantile(c_df[nbc], [0.25, 0.75])]
            c_iqr = f"{c_iqr[0]}; {c_iqr[1]}"
        c_res+=[c_median]
        c_res+=[c_iqr]
        if nbc in ['targetHF_score', 't_dur', 't_birth', '0_24_n_eps_']:
            c_res+=[f"{c_median:.{decimals}f} ({c_iqr})" ]
        else:
            c_res+=[f"{c_median} ({c_iqr})" ]
    
    c_flwp_dur = gmm_df.t_dur.sum()
    c_n_cases = gmm_df.t_HF.sum()
    c_IR = (1000*c_n_cases) / (c_flwp_dur/DAYS_IN_YEAR) # i.e., *X* number of HF cases per 1000 person-years
    c_res+= [c_IR]

        
    res  = res + [c_res]
    # break


out_df = pd.DataFrame.from_records(res)
out_df.columns = res_colnames
out_df = out_df.sort_values(by=['HF%'], ascending=F)

